namespace WorkerAdmin\Infrastructure\Settings {
 final class GlobalSettingsProvider implements \WorkerAdmin\Contracts\SettingsProvider {public function get(string $k,$d=null){return \setting($k,$d);}public function bool(string $k,bool $d=false):bool{return filter_var($this->get($k,$d),FILTER_VALIDATE_BOOLEAN);}public function int(string $k,int $d=0):int{return(int)$this->get($k,$d);}}
}
namespace WorkerAdmin\Infrastructure\Security {
 final class GlobalPrivateValueCipher implements \WorkerAdmin\Contracts\PrivateValueCipher {public function hmac(string $p,string $c):string{return hash('sha256',$c.':'.$p);}public function encrypt(string $p,string $c):?string{return'FIXTURE:'.$p;}public function decrypt(string $p,string $c):string{return substr($p,8);}}
}
