namespace WorkerAdmin\Foundation {
 use WorkerAdmin\Core\Database;
 final class OrderApplicationContainer {
  private Database $db;public function __construct(Database $db){$this->db=$db;}
  public function settings(){return new \WorkerAdmin\Infrastructure\Settings\GlobalSettingsProvider();}public function cipher(){return new \WorkerAdmin\Infrastructure\Security\GlobalPrivateValueCipher();}
  public function deal(){return new \WorkerAdmin\Application\Order\OrderDeal(new \WorkerAdmin\Infrastructure\Persistence\DatabaseOrderDealRepository($this->db,new \WorkerAdmin\Infrastructure\Settings\GlobalSettingsProvider()),new \WorkerAdmin\Infrastructure\Agreements\PlatformWorkerAgreementVersionProvider($this->db));}
  public function quoteSelection(){return new \WorkerAdmin\Application\Order\OrderQuoteSelection(new \WorkerAdmin\Infrastructure\Persistence\DatabaseOrderQuoteSelectionRepository($this->db,new \WorkerAdmin\Infrastructure\Settings\GlobalSettingsProvider()));}
  public function appointment(){return new \WorkerAdmin\Application\Order\OrderAppointment(new \WorkerAdmin\Infrastructure\Persistence\DatabaseOrderAppointmentRepository($this->db));}
  public function invitation(){return new \WorkerAdmin\Application\Order\OrderInvitationClaim(new \WorkerAdmin\Infrastructure\Persistence\DatabaseOrderInvitationRepository($this->db),new \WorkerAdmin\Infrastructure\Settings\GlobalSettingsProvider());}
  public function fulfillment(){return new ExpansionFulfillmentAdapter($this->db);}
 }
 final class ExpansionFulfillmentAdapter {
  private Database $db;public function __construct(Database $db){$this->db=$db;}
  public function execute(string $route,array $actor,array $body):array{
   if(!empty($actor['is_admin'])||!empty($actor['business_admin']))throw new \RuntimeException('actor inherited admin');
   $o=$this->db->fetch('SELECT * FROM orders WHERE public_no=:no',['no'=>$body['order_id']]);
   $measurement=new \WorkerAdmin\Infrastructure\Persistence\PlatformPricingAwareOrderMeasurementCompletionRepository(new \WorkerAdmin\Infrastructure\Persistence\DatabaseOrderMeasurementCompletionRepository($this->db),$this->db);
   if($route==='orders.measurement.submit')return$measurement->complete($actor,$o,48);
   if($route==='orders.measurement.rework')return$measurement->requestRework($actor,$o,(string)$body['reason']);
   $completion=new \WorkerAdmin\Infrastructure\Persistence\DatabaseOrderCompletionRepository($this->db);
   if($route==='fulfillment.complete')return$completion->complete($actor,$o,(string)($body['description']??'TEST'),0,'',72);
   if($route==='fulfillment.accept'){if((int)$actor['user_id']!==(int)$o['user_id'])throw new \RuntimeException('customer ownership');return$o['workflow_profile']==='measurement'?$measurement->accept($actor,$o,5,15,30):$completion->accept($actor,$o,5);}
   throw new \RuntimeException('unsupported test routing '.$route);
  }
 }
}
