 function exRollbackProbe(Database $db,callable $probe):void{try{$db->transaction(static function()use($probe):void{$probe();throw new \LogicException('rollback-negative-probe');});}catch(\LogicException $e){if($e->getMessage()!=='rollback-negative-probe')throw$e;}}
 function exFinanceCleanupProbes(Database $db,$c,string $public,int $order):void{
